export const name = 'claudian-lifecycle';

export function apply() {
  let ended = false;
  const exit = () => {
    if (ended) return;
    ended = true;
    if (process.listenerCount('SIGTERM') > 0) process.emit('SIGTERM'); else process.exit(0);
  };
  process.stdin.on('end', exit).on('error', exit).resume();
}
